const DEPARTMENTS=['Water Works','GHMC — Roads','GHMC — Sanitation','TSSPDCL — Electricity','Street Lighting Cell','Sewerage & Drainage','Public Health Department','Public Safety Cell','Environment & Parks','Transport Department','Human Verification Queue'];
